def sumOfGoodSubsequences(nums):
    MOD = 10 ** 9 + 7
    cnt = {}
    ssum = {}
    for x in nums:
        base = cnt.get(x - 1, 0) + cnt.get(x + 1, 0) + 1
        s = ssum.get(x - 1, 0) + ssum.get(x + 1, 0) + x * base
        cnt[x] = (cnt.get(x, 0) + base) % MOD
        ssum[x] = (ssum.get(x, 0) + s) % MOD
    return sum(ssum.values()) % MOD
